//! The provider derivation against the Python factory.
//!
//! `tests/fixtures/providers.json` was generated by running
//! `RepoProviderFactory.from_toolkit_config` (the way
//! `tool_operations.generate_wiki` calls it) over each `repo_config`, with
//! the clone URL's userinfo split off into the `Authorization` value git
//! sends for it. The Rust port must give the same host, URL, identifier,
//! branch, auth method and header — or the same error — except where the
//! port deliberately differs, listed in `DELIBERATE` with the reason.

use elitea_engine_core::errors::ErrorType;
use elitea_repo_ingest::providers::clone_target;
use serde_json::{Value, json};
use std::path::PathBuf;

/// Cases where the port does better than Python on purpose, with what it
/// gives instead.
fn deliberate(name: &str) -> Option<Value> {
    match name {
        // Python dropped `scm/` for a Server repository URL with no
        // `project`, building a URL the server does not serve.
        "bitbucket server url repository" | "bitbucket server ssh scm" => Some(json!({
            "url": "https://bitbucket.example.com/scm/PROJ/repo.git",
        })),
        // Python cloned `owner/repo/tree/dev.git`; the path is a valid
        // URL path, so the port keeps it too (the server answers 404).
        _ => None,
    }
}

#[test]
fn every_python_case_derives_the_same_target() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/providers.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let cases: Vec<Value> = serde_json::from_str(&text).unwrap_or_else(|e| panic!("{e}"));
    assert!(cases.len() >= 40, "the table lost cases");
    for case in cases {
        let name = case["name"].as_str().unwrap_or_default();
        let derived = clone_target(&case["repo_config"]);
        if let Some(error) = case.get("error") {
            let refused = derived
                .err()
                .unwrap_or_else(|| panic!("{name}: derived a target"));
            assert_eq!(error["type"], "ValueError", "{name}");
            assert_eq!(refused.error_type, ErrorType::Value, "{name}");
            assert_eq!(
                refused.message,
                error["message"].as_str().unwrap_or_default(),
                "{name}"
            );
            continue;
        }
        let target = derived.unwrap_or_else(|e| panic!("{name}: {e}"));
        let mut expected = case["expected"].clone();
        if let Some(Value::Object(overrides)) = deliberate(name) {
            for (key, value) in overrides {
                expected[key] = value;
            }
        }
        let got = json!({
            "provider": target.provider().value(),
            "host": target.host(),
            "url": target.url(),
            "repo_identifier": target.repo_identifier(),
            "branch": target.branch(),
            "auth_method": target.auth_method(),
            "authorization": target.authorization().map(|a| a.expose().to_owned()),
        });
        let expected_host = expected["host"].as_str().unwrap_or_default().to_lowercase();
        expected["host"] = Value::String(expected_host);
        assert_eq!(got, expected, "{name}");
    }
}
